<?php ob_start(); ?><div class="card"><h1>Nova campanha</h1><form method="post" action="/campanhas" enctype="multipart/form-data"><input type="hidden" name="_csrf" value="<?=$csrf?>"><label>Nome da campanha<input name="title" required></label><label>Assunto<input name="subject" required></label><label>Mensagem HTML<textarea id="body" name="body" required placeholder="Olá, {nome}!"></textarea></label><label>Imagem (JPEG, PNG, GIF ou WebP, até 10 MB)<input id="image" name="image" type="file" accept="image/*"></label><label>Descrição da imagem<input name="image_description"></label><img id="preview" style="max-width:320px;display:none"><label>Site<input name="site" type="url"></label><label>Instagram<input name="instagram" type="url"></label><label>LinkedIn<input name="linkedin" type="url"></label><label>Facebook<input name="facebook" type="url"></label><button class="btn">Salvar rascunho</button></form></div><script>document.getElementById('image').onchange=e=>{const f=e.target.files[0],p=document.getElementById('preview');if(f){p.src=URL.createObjectURL(f);p.style.display='block'}}</script><?php $body=ob_get_clean();$title='Nova campanha';require __DIR__.'/layout.php'; ?>
